escalation_contract:
{
  "v1": {
    "triggers": [
      "execution authority granted",
      "implementation needed",
      "unknown root cause",
      "preflight fails",
      "live incident scope dominates"
    ],
    "targets": {
      "execution authority granted": "slice.operational-execution",
      "implementation needed": "slice.hybrid-implementation-operation",
      "unknown root cause": "slice.debug-root-cause",
      "preflight fails": "handoff_or_block",
      "live incident scope dominates": "incident_or_operational-execution"
    },
    "representation": [
      "variant-selection-record",
      "follow-up Slice",
      "handoff.md"
    ],
    "hidden_second_lifecycle_allowed": false
  },
  "native": "Execution authority creates Operational Execution; implementation creates Lightweight/Full; unknown cause creates Debug; Hybrid creates separate implementation and Operational Slice graph. Preserve target, evidence, authority, owner and proof."
}
